"""Persist the manually read performance-evaluation chapter and cross references."""
import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def write(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')


def main():
    chapter = next(c for c in json.loads((ROOT/'outline.json').read_text(encoding='utf-8'))['chapters'] if c['id']=='S3C7')
